"""Verify the parquet data file which is generated by the pure VB.NET parquet
writer, the expectation values are dumped by the test program in json format.

usage:
    python verify_vb_output.py <parquet-file> <expect-json>

The script prints one line for each check:

    PASS <name>
    FAIL <name> expected=<...> actual=<...>
    SUMMARY pass=<n> fail=<n>

The test program counts the PASS/FAIL lines and writes the result into the
debug audit report.
"""

import datetime
import json
import math
import sys

import pyarrow as pa
import pyarrow.parquet as pq

UTC = datetime.timezone.utc

TYPE_CHECKS = {
    "int32": pa.types.is_int32,
    "int64": pa.types.is_int64,
    "float": pa.types.is_float32,
    "double": pa.types.is_float64,
    "bool": pa.types.is_boolean,
    "string": pa.types.is_string,
    "timestamp_ms": lambda t: pa.types.is_timestamp(t) and t.unit == "ms",
}

passed = 0
failed = 0


def report(ok, name, expected=None, actual=None):
    global passed, failed

    if ok:
        passed += 1
        sys.stdout.write("PASS %s\n" % name)
    else:
        failed += 1
        sys.stdout.write("FAIL %s expected=%r actual=%r\n" % (name, expected, actual))


def epoch_millis(value):
    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=UTC)

        return int(round(value.timestamp() * 1000))

    if isinstance(value, datetime.date):
        return int(round(datetime.datetime(value.year, value.month, value.day,
                                          tzinfo=UTC).timestamp() * 1000))

    return None


def value_equals(expected, actual):
    if isinstance(expected, str) and expected == "NaN":
        return isinstance(actual, float) and math.isnan(actual)

    if expected is None:
        return actual is None

    if isinstance(expected, str) and expected[:2] == "ts":
        expected = expected[2:]

    if isinstance(expected, str) and len(expected) >= 20 and expected[4] == "-" and expected[10] == "T":
        if actual is None:
            return False

        text = expected.replace("Z", "+00:00")
        moment = datetime.datetime.fromisoformat(text)

        return epoch_millis(moment) == epoch_millis(actual)

    if isinstance(expected, bool) or isinstance(actual, bool):
        return bool(expected) == bool(actual)

    if isinstance(expected, (int, float)) and isinstance(actual, (int, float)):
        if math.isnan(expected) or math.isnan(actual):
            return math.isnan(expected) and math.isnan(actual)

        return abs(float(actual) - float(expected)) <= 1e-9 * max(1.0, abs(float(expected)))

    return expected == actual


def main():
    if len(sys.argv) < 3:
        sys.stderr.write("usage: python verify_vb_output.py <parquet-file> <expect-json>\n")
        return 2

    with open(sys.argv[2], "r", encoding="utf-8-sig") as handle:
        expect = json.load(handle)

    table = pq.read_table(sys.argv[1])
    names = set(table.column_names)

    report(table.num_rows == expect["rows"], "rows", expect["rows"], table.num_rows)

    for column in expect["columns"]:
        name = column["name"]

        if name not in names:
            report(False, "column %s exists" % name, True, False)
            continue

        report(True, "column %s exists" % name)

        field = table.schema.field(name)
        check = TYPE_CHECKS.get(column["type"])

        if check is None:
            report(False, "column %s type %s" % (name, column["type"]), "known type", column["type"])
        else:
            report(check(field.type), "column %s type %s" % (name, column["type"]),
                   column["type"], str(field.type))

        actual_values = table.column(name).to_pylist()
        expected_values = column["values"]

        if len(actual_values) != len(expected_values):
            report(False, "column %s length" % name, len(expected_values), len(actual_values))
            continue

        for index in range(len(expected_values)):
            report(value_equals(expected_values[index], actual_values[index]),
                   "column %s[%d]" % (name, index),
                   expected_values[index], actual_values[index])

    sys.stdout.write("SUMMARY pass=%d fail=%d\n" % (passed, failed))

    return 0 if failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
